-- ARMEND - seed Kitchen Stock (HARA): 119 item dari "Daily Kitchen Hara NEW.xlsx"
-- Harga & stok awal belum diisi (harga dari pricelist/import resep; stok awal dari opname).
-- Jalankan sekali di Supabase SQL Editor.

select 'hara-kitchen', 'Kitchen Stock', o.id, 'area', 'kitchen', 2
from public.outlets o where o.name = 'HARA' and o.kind = 'group'
on conflict (id) do nothing;

on conflict (id) do nothing;
